import { defineConfig } from 'astro/config';

// StatuteRates has a permanent production domain, so a build that omits SITE_URL must still emit
// correct canonicals. Preview/GitHub Pages builds can override this explicitly at deploy time.
const SITE_URL = process.env.SITE_URL || 'https://statuterates.com';

// sitemap.xml is generated by src/pages/sitemap.xml.js (self-contained, no integration dependency).
export default defineConfig({
  site: SITE_URL,
  // Astro 7 changed its default to JSX whitespace rules, which remove line-break spaces around
  // inline links/emphasis. Keep Astro 6's lossless HTML-aware compression for existing prose.
  compressHTML: true,
  trailingSlash: 'ignore',
  build: {
    format: 'directory', // clean URLs: /rates/<slug>/ -> index.html
  },
});
